type UndoCandidate = { id: string; matchNumber: number; status: string; competitor1?: unknown; competitor2?: unknown };

export function isScoredResult(match: UndoCandidate): boolean {
  if (match.status !== 'completed') return false;
  // Bye advancements (a missing competitor) are generated by the bracket,
  // have no result audit entry, and cannot be undone.
  if ('competitor1' in match || 'competitor2' in match) {
    return match.competitor1 != null && match.competitor2 != null;
  }
  return true;
}

/**
 * The match Ctrl+Z undoes. The result this station just recorded wins when it
 * is completed (and nothing is chosen while it is listed but not completed);
 * with no recorded result here, the highest-numbered scored match. Match
 * numbers alone are not chronological in double elimination (a losers-bracket
 * match can outnumber a later winners-bracket result).
 */
export function latestCompletedMatchId(matches: UndoCandidate[], preferredId: string | null = null): string | null {
  const scored = matches.filter(isScoredResult);
  if (preferredId && scored.some((match) => match.id === preferredId)) return preferredId;
  // The recorded match is listed but not completed: either the refresh has
  // not rendered yet or another station undid it. Never fall back to some
  // other match then; Ctrl+Z would undo a result nobody meant.
  if (preferredId && matches.some((match) => match.id === preferredId)) return null;
  return scored.sort((a, b) => b.matchNumber - a.matchNumber)[0]?.id ?? null;
}
